import{_ as o,o as t,c as s,a3 as a}from"./chunks/framework.CCylkYel.js";const m=JSON.parse('{"title":"USB protocol","description":"","frontmatter":{},"headers":[],"relativePath":"developers/protocol.md","filePath":"developers/protocol.md"}'),i={name:"developers/protocol.md"};function r(n,e,d,c,l,h){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="usb-protocol" tabindex="-1">USB protocol <a class="header-anchor" href="#usb-protocol" aria-label="Permalink to &quot;USB protocol&quot;">​</a></h1><p>The s32 CLI is the supported client for the S32 Editor USB interface. This page is the overview for anyone writing their own.</p><h2 id="interface" tabindex="-1">Interface <a class="header-anchor" href="#interface" aria-label="Permalink to &quot;Interface&quot;">​</a></h2><p>A vendor USB interface: VID <code>0483</code>, PID <code>A56E</code>, bulk endpoints <code>0x05</code> (out) and <code>0x85</code> (in). One client at a time, with no password (<a href="./connecting#usb">Connect</a>).</p><p>The protocol version is <strong>5</strong>. <code>hello</code> reports the protocol of the session, and a client that speaks a version the firmware does not serve is refused instead of misread: firmware 1.1.5 serves <strong>4 and 5</strong>, older firmware serves one of them. Offer 5 first; if the refusal names 4, send one more <code>hello</code> with 4 and keep using it. The s32 CLI version (<code>s32 --version</code>) is separate from the firmware version.</p><p>Protocol 5 implies every capability bit of protocol 4: a 1.1.5 <code>hello</code> reports only the new protocol-5 bits in its capability mask and the runtime facts in a <code>presence</code> byte instead (bit 0 microSD card; bit 1 is reserved). On protocol 4 the mask still names each feature, exactly as in 1.1.4.</p><table tabindex="0"><thead><tr><th>Protocol-5 bit</th><th>Mask</th><th>Feature</th><th>Named line</th><th>Firmware</th></tr></thead><tbody><tr><td>0</td><td><code>0x00000001</code></td><td>Opening a Step Seq step&#39;s parameter with that parameter highlighted (<code>view nav … step=N field=NAME</code>)</td><td><code>stepFieldNav yes</code></td><td>1.1.5</td></tr></tbody></table><h2 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h2><ol><li>Claim the interface.</li><li>Send <code>hello</code>. Check that <code>protocolVersion</code> is 4 or 5 (a refusal names the protocol to use).</li><li>Send commands. Each request is a CRC-checked frame. The reply carries a status and an optional payload.</li><li>Subscribe to events for live updates (<code>watch</code> in the s32 CLI).</li></ol><p>Every reply carries the command and <code>seq</code> of the request it answers. Match both. A client stopped mid-transfer leaves unread replies behind, and the next client gets them first. The s32 CLI starts at a random <code>seq</code>, drops anything waiting before <code>hello</code>, and skips replies that don&#39;t match. A new <code>hello</code> ends any push or pull the last client left open.</p><p>Two statuses come from the rules, not from errors: <code>Forbidden</code> (that action is panel-only) and <code>TooMany</code> (changes sent faster than the S32 takes them; wait and retry).</p><h2 id="discovering-the-device" tabindex="-1">Discovering the device <a class="header-anchor" href="#discovering-the-device" aria-label="Permalink to &quot;Discovering the device&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --usb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --usb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-schema-json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">s32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> layout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --emit-layout-json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> layout.json</span></span></code></pre></div><p><code>schema</code> lists device types, parameter names and enum tables (macro modes, menus). <code>layout</code> describes the <code>.s32p</code> project file for tools that decode it. It needs no S32.</p><p><code>hello</code> also reports the feature lines and, for programs, the capability mask of its protocol. Protocol 5 implies all of the protocol-4 features, so its mask holds only the protocol-5 bits above and the named lines carry the rest; on protocol 4 each is a bit. Follow the named lines (<code>rackStart yes</code>, <code>navTarget yes</code>, <code>stepFieldNav yes</code>, ...) or the JSON keys rather than the raw mask. <code>stepFieldNav</code> is always <code>no</code> on protocol 4.</p><p>Protocol 5 implies the one-mapping rule: a mapping write from the editor replaces the parameter&#39;s other knob or MIDI mapping (protocol 4, bit 19 <code>524288</code>).</p><p>It implies CLEAR RACK resets, and DUPLICATE RACK copies, the rack&#39;s BYPASS and IN SNAPSHOT (protocol 4, bit 20 <code>1048576</code>).</p><p>It implies the rack start rules: REMOVE never refuses the first device, a needed MIDI IN or CLOCK goes first, a top CLOCK stays on top under MOVE, a load keeps every device, and DUPLICATE RACK keeps the source order (protocol 4, bit 21 <code>2097152</code>).</p><p>It implies a Step Seq step changed on the S32 is reported as an event; re-read the pattern when it arrives (protocol 4, bit 22 <code>4194304</code>).</p><p>It implies <code>view nav</code> (and the editor&#39;s &quot;show on the S32&quot;) can open a Step Seq or Euclid setting row, or focus a step or layer: <code>row=</code>, <code>step=</code> and <code>layer=</code> (protocol 4, bit 23 <code>8388608</code>).</p><p>Names such as <code>mode=cc</code>, <code>clockMode=internal</code> and <code>view nav racks</code> are s32 CLI words. On the wire they are the integers in the schema&#39;s enum tables.</p>`,21)])])}const k=o(i,[["render",r]]);export{m as __pageData,k as default};
